import { createProgram,compileProgram } from './automation-language.js';

export const LANES=3,SLOTS=3,WAVE_COUNT=5;
const laneY=[130,300,470],slotX=[215,390,565];
const TYPES={scout:{id:1,name:'Scout',hp:34,speed:43,armor:0,hit:8,color:'#e6a15d',size:11},raider:{id:2,name:'Raider',hp:67,speed:27,armor:1,hit:13,color:'#c66d55',size:15},brute:{id:3,name:'Iron Brute',hp:130,speed:16,armor:5,hit:19,color:'#647583',size:19},drake:{id:4,name:'Ash Drake',hp:78,speed:34,armor:2,hit:11,color:'#8459a2',size:16}};
const AMMO={arrow:{cost:0,damage:17,speed:660,color:'#f7e5ae'},frost:{cost:2,damage:10,speed:540,color:'#90e4ed',slow:3.8},cannon:{cost:4,damage:56,speed:420,color:'#f6945c',splash:68}};
export {TYPES,AMMO};
export const towerPos=(lane,col)=>({x:slotX[col],y:laneY[lane],lane,col});
export const newKingdom=()=>({version:1,time:0,wave:0,phase:'planning',coins:170,mana:20,maxMana:20,castleHP:180,maxCastleHP:180,expanded:false,stars:0,towers:[],walls:[],enemies:[],queue:[],spawnTimer:0,projectiles:[],ledger:[],missions:[],message:'Raise your first watchtowers, deploy a defense policy, and start the first wave.',policy:'',policyError:'',totals:{shots:0,stopped:0,leaked:0,kills:0,breaches:0,shotTypes:{arrow:0,frost:0,cannon:0},cannonShots:0,armoredHits:0,brutesStopped:0,frostSlows:0,branches:0,lanes:[]}});
export function cloneKingdom(s){const v=JSON.parse(JSON.stringify(s));v.checkpoint=undefined;return v;}
const typesForWave=n=>{
  if(n===1)return['scout','scout','raider','scout','scout','raider','scout','scout'];
  if(n===2)return['raider','scout','brute','scout','raider','drake','scout','brute','raider'];
  if(n===3)return['drake','scout','brute','raider','scout','drake','brute','raider','scout','brute'];
  if(n===4)return['brute','drake','raider','brute','scout','drake','brute','raider','brute','drake','scout'];
  return['brute','drake','brute','raider','drake','brute','brute','drake','raider','brute','scout','drake'];
};
export const slots=()=>Array.from({length:LANES},(_,lane)=>Array.from({length:SLOTS},(_,col)=>towerPos(lane,col)));
export function build(s,kind,lane,col){
  if(s.phase==='battle')return{ok:false,message:'Build between waves, when the kingdom is safe.'};
  if(!Number.isInteger(lane)||lane<0||lane>=LANES||!Number.isInteger(col)||col<0||col>=SLOTS)return{ok:false,message:'Choose one of the marked lane slots.'};
  if(col===2&&!s.expanded)return{ok:false,message:'Claim the Eastern Ridge before building there.'};
  if(s.towers.some(t=>t.lane===lane&&t.col===col))return{ok:false,message:'That ridge already has a watchtower.'};
  if(kind!=='tower')return{ok:false,message:'Choose a watchtower to guard this ridge.'};
  if(s.coins<45)return{ok:false,message:'A watchtower costs 45 coins.'};
  const p=towerPos(lane,col);s.coins-=45;s.towers.push({...p,level:1,cooldown:.1,range:275});s.message=`Watchtower raised on ${['North','Middle','South'][lane]} Lane.`;return{ok:true};
}
export function expandKingdom(s){if(s.phase==='battle')return{ok:false,message:'Expand in the planning phase.'};if(s.expanded)return{ok:false,message:'The Eastern Ridge is already part of the kingdom.'};if(s.coins<80)return{ok:false,message:'Claiming the Eastern Ridge costs 80 coins.'};s.coins-=80;s.expanded=true;s.message='Eastern Ridge claimed! Three high-ground tower positions are open.';return{ok:true};}
export function upgradeTower(s,lane,col){const t=s.towers.find(t=>t.lane===lane&&t.col===col);if(!t)return{ok:false,message:'Select a watchtower to upgrade.'};if(t.level>=3)return{ok:false,message:'This tower has reached level 3.'};const price=35*t.level;if(s.coins<price)return{ok:false,message:`This upgrade costs ${price} coins.`};s.coins-=price;t.level++;t.range+=20;t.cooldown=Math.max(.55,t.cooldown-.1);s.message=`Watchtower upgraded to level ${t.level}. More range and a faster reload.`;return{ok:true};}
export function buildWall(s,lane){if(s.phase==='battle')return{ok:false,message:'Build between waves.'};if(s.walls.some(w=>w.lane===lane))return{ok:false,message:'A reinforced roadblock already guards this lane.'};if(s.coins<30)return{ok:false,message:'A roadblock costs 30 coins.'};s.coins-=30;s.walls.push({lane,x:148,hp:90,maxHp:90});s.message=`A roadblock now slows ${['North','Middle','South'][lane]} Lane.`;return{ok:true};}
export function startWave(s){if(s.phase!=='planning')return{ok:false,message:'Finish planning before dispatching a wave.'};if(s.wave>=WAVE_COUNT)return{ok:false,message:'The kingdom is already secure.'};s.checkpoint={coins:s.coins,mana:s.mana,castleHP:s.castleHP,expanded:s.expanded,towers:JSON.parse(JSON.stringify(s.towers)),walls:JSON.parse(JSON.stringify(s.walls)),wave:s.wave};s.wave++;s.phase='battle';s.queue=typesForWave(s.wave).map((type,i)=>({type,lane:(i*2+Math.floor(i/3))%LANES}));s.enemies=[];s.spawnTimer=.2;s.projectiles=[];s.policyError='';s.message=`Wave ${s.wave} approaches! Towers run your policy as each threat enters range.`;return{ok:true};}
export function retryWave(s){if(s.phase!=='lost'||!s.checkpoint)return{ok:false};const p=s.checkpoint;s.coins=p.coins;s.mana=p.mana;s.castleHP=p.castleHP;s.expanded=p.expanded;s.towers=p.towers;s.walls=p.walls;s.wave=p.wave;s.phase='planning';s.enemies=[];s.queue=[];s.projectiles=[];s.policyError='';s.message=`Wave ${p.wave+1} reset. Rework your policy or fortify the lanes before retrying.`;return{ok:true};}
export const POLICY_SENSORS=['lane','wave','mana','castle_health','enemy_count','enemy_type','enemy_health','enemy_distance','nearby','is_armored','is_fast'];
export const POLICY_ACTIONS=['shoot'];
export function targetFor(s,tower){return s.enemies.filter(e=>e.lane===tower.lane&&e.x<=tower.x+tower.range&&e.x>60).sort((a,b)=>a.x-b.x)[0]??null;}
export function readPolicy(s,tower,target,name,args){switch(name){case'lane':return tower.lane;case'wave':return s.wave;case'mana':return Math.floor(s.mana);case'castle_health':return s.castleHP;case'enemy_count':return s.enemies.filter(e=>e.lane===tower.lane&&e.x>60).length;case'enemy_type':return target?.id??0;case'enemy_health':return target?Math.ceil(target.hp):0;case'enemy_distance':return target?Math.max(0,Math.round(target.x-tower.x)):999;case'nearby':return target?s.enemies.filter(e=>e.lane===tower.lane&&Math.abs(e.x-target.x)<=75).length:0;case'is_armored':return Number(Boolean(target&&target.armor>=2));case'is_fast':return Number(Boolean(target&&target.speed>=32));default:throw Error(`Unknown defense sensor ${name}.`);}}
function towerFire(s,tower,target,ammoName,stats){const ammo=AMMO[ammoName];if(!ammo)return{ok:false,result:0,message:'Choose arrow, frost, or cannon ammunition.'};if(s.mana<ammo.cost)return{ok:false,result:0,message:`Need ${ammo.cost} mana for ${ammoName}; ${Math.floor(s.mana)} available.`};s.mana-=ammo.cost;stats.shots++;stats.shotTypes[ammoName]++;s.totals.shots++;s.totals.shotTypes[ammoName]++;s.totals.lanes.push(tower.lane);if(ammoName==='cannon')s.totals.cannonShots++;s.projectiles.push({x:tower.x,y:tower.y,enemyId:target.uid,lane:tower.lane,enemyType:target.type,ammo:ammoName,speed:ammo.speed,damage:ammo.damage,splash:ammo.splash||0,slow:ammo.slow||0,level:tower.level,color:ammo.color});tower.cooldown=1.25-(tower.level-1)*.16;return{ok:true,result:1,message:`${['North','Middle','South'][tower.lane]} Lane · ${ammoName} · ${TYPES[target.type].name}`};}
function runPolicy(s,tower,ast){const target=targetFor(s,tower);if(!target)return;const stats={shots:0,branches:0,shotTypes:{arrow:0,frost:0,cannon:0}};try{const vm=createProgram(ast,{actions:POLICY_ACTIONS,sensors:POLICY_SENSORS,read:(name,args)=>readPolicy(s,tower,target,name,args)});let resume;for(let i=0;i<2000;i++){const next=vm.iterator.next(resume);resume=undefined;stats.branches=vm.stats.branches;if(next.done)break;if(next.value.kind==='action'){if(stats.shots>=2)throw Error(`Line ${next.value.line}: a tower can fire twice each policy check.`);const result=towerFire(s,tower,target,next.value.args[0],stats);if(!result.ok)throw Error(`Line ${next.value.line}: ${result.message}`);resume=result.result;}if(i===1999)throw Error('Policy step limit reached.');}s.totals.branches+=stats.branches;if(stats.shots)s.ledger.push({time:s.time,line:tower.lane+1,message:`Lane ${tower.lane+1} tower fires ${stats.shotTypes.arrow?'arrow':stats.shotTypes.frost?'frost':'cannon'} at ${TYPES[target.type].name}.`});
  }catch(error){s.policyError=error.message;s.phase='error';s.message=`Defense policy paused · ${error.message}`;}}
function spawnAtLane(s){const queued=s.queue.shift(),type=queued.type,info=TYPES[type],n=s.totals.stopped+s.totals.leaked+s.enemies.length;s.enemies.push({uid:`${s.wave}-${s.time.toFixed(2)}-${n}`,type,id:info.id,hp:info.hp,speed:info.speed,armor:info.armor,hit:info.hit,x:970,lane:queued.lane,slow:0});}
function damageEnemy(s,e,damage){const actual=Math.max(2,damage* (e.armor>0?.62:1)-e.armor);e.hp-=actual;if(e.hp<=0){s.totals.kills++;s.totals.stopped++;if(e.type==='brute')s.totals.brutesStopped++;s.enemies=s.enemies.filter(q=>q!==e);return true;}return false;}
export function stepKingdom(s,seconds,ast){const dt=Math.max(0,Math.min(.05,seconds));if(s.phase!=='battle')return;s.time+=dt;s.mana=Math.min(s.maxMana,s.mana+1.55*dt);s.spawnTimer-=dt;if(s.queue.length&&s.spawnTimer<=0){spawnAtLane(s);s.spawnTimer=1.25;}
  for(const t of s.towers){t.cooldown-=dt;if(ast&&t.cooldown<=0&&targetFor(s,t))runPolicy(s,t,ast);if(s.phase==='error')return;}
  for(const e of [...s.enemies]){if(!s.enemies.includes(e))continue;const wall=s.walls.find(w=>w.lane===e.lane&&e.x<=w.x+e.speed*dt&&e.x>w.x-24);if(wall){wall.hp-=e.hit*dt;if(wall.hp<=0){s.walls=s.walls.filter(w=>w!==wall);s.message=`A ${TYPES[e.type].name} broke through the lane ${e.lane+1} roadblock.`;}continue;}if(e.slow>0)e.slow=Math.max(0,e.slow-dt);e.x-=e.speed*dt*(e.slow>0?.42:1);if(e.x<=79){s.castleHP-=e.hit;s.totals.leaked++;s.totals.breaches++;s.enemies=s.enemies.filter(q=>q!==e);s.message=`${TYPES[e.type].name} breached the gates. Keep health: ${s.castleHP}.`;if(s.castleHP<=0){s.castleHP=0;s.phase='lost';s.message=`The inner keep fell during wave ${s.wave}. Review the defense policy, reinforce the lanes and try this wave again.`;return;}}}
  for(const p of [...s.projectiles]){p.x+=p.speed*dt;const e=s.enemies.find(e=>e.uid===p.enemyId)||s.enemies.filter(e=>e.lane===p.lane&&Math.abs(e.x-p.x)<18).sort((a,b)=>a.x-b.x)[0];if(e&&Math.abs(e.x-p.x)<25){if(p.slow){e.slow=Math.max(e.slow,p.slow);s.totals.frostSlows++;}if(p.ammo==='cannon'&&p.enemyType==='brute')s.totals.armoredHits++;damageEnemy(s,e,p.damage*(1+(p.level-1)*.35));if(p.splash){for(const nearby of [...s.enemies])if(nearby!==e&&nearby.lane===e.lane&&Math.abs(nearby.x-e.x)<p.splash)damageEnemy(s,nearby,p.damage*.35);}s.projectiles=s.projectiles.filter(q=>q!==p);continue;}if(p.x>1000)s.projectiles=s.projectiles.filter(q=>q!==p);}
  if(!s.queue.length&&!s.enemies.length){s.phase=s.wave>=WAVE_COUNT?'won':'cleared';s.stars++;s.coins+=42+s.wave*12;s.mana=Math.min(s.maxMana,s.mana+8);s.message=s.phase==='won'?'All five waves repelled! The kingdom stands.':`Wave ${s.wave} held! +${42+s.wave*12} treasury · Expand, upgrade, or deploy for the next wave.`;}}
export function deployPolicy(s,source){try{const ast=compileProgram(source);s.policy=source;s.policyError='';s.ast=ast;if(s.phase==='error'){s.phase='battle';s.message='Defense policy deployed. The attack resumes.';}else if(s.phase==='planning')s.message='Policy deployed. Your watchtowers will execute these conditions during a wave.';return{ok:true,ast};}catch(e){return{ok:false,message:e.message};}}
export function postWave(s){if(s.phase==='cleared'){s.phase='planning';s.message=`Plan for wave ${s.wave+1}. Raise defenses and update your policy.`;}}
export function completedMission(s,id){switch(id){case'one':return s.totals.shots>=8&&s.totals.branches>0;case'armor':return s.totals.armoredHits>=4&&s.totals.brutesStopped>=4;case'fast':return s.totals.frostSlows>=4;case'lanes':return new Set(s.totals.lanes).size>=3;case'keep':return s.castleHP>=150&&s.wave>=3;case'victory':return s.phase==='won';default:return false;}}
